package config

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// TemplateVersion identifies the bundled example configuration format.
const TemplateVersion = 1

// ErrConfigExists is returned when generating a config would overwrite one.
var ErrConfigExists = errors.New("config file already exists")

const configTemplate = `# pida configuration file, version 1
#
# Generated by "pida config". Every option can also be supplied as an
# environment variable or a "pida serve" flag; flags win, then the process
# environment, then this file. Values are KEY=value pairs. Quote values that
# contain spaces or "#".

# ---------------------------------------------------------------- server
# HTTP port to listen on. The server binds 127.0.0.1 unless a password is set
# (then it binds 0.0.0.0) or development mode is enabled.
PORT=3000

# Where conversations, settings, and uploaded files are stored.
# "pida serve" defaults to ~/.pida when this is empty.
DATA_DIR=

# http, https, or both. "both" redirects plain HTTP to the HTTPS port.
HTTP_MODE=http

# HTTPS port used by the https and both modes.
HTTPS_PORT=3443

# PEM certificate and key used for HTTPS. Create them with mkcert:
#   mkcert -cert-file certs/localhost.pem -key-file certs/localhost-key.pem localhost 127.0.0.1
TLS_CERT_FILE=certs/localhost.pem
TLS_KEY_FILE=certs/localhost-key.pem

# ---------------------------------------------------------------- security
# Access password for HTTP Basic Auth. Required in production. Leave empty for
# loopback-only use.
DEMO_PASSWORD=

# Set to "production" to require a password and bind all interfaces.
# NODE_ENV=production

# ---------------------------------------------------------------- notifications
# Webhook URL for task notifications. Empty disables notifications.
NOTIFY_WEBHOOK_URL=

# Webhook payload kind: generic, slack, or discord.
NOTIFY_WEBHOOK_KIND=generic

# When to send notifications: errors, always, or never.
NOTIFY_MODE=errors

# ---------------------------------------------------------------- knowledge
# Absolute path to an Obsidian vault exposed to the read-only knowledge tools.
OBSIDIAN_ROOT=

# Comma-separated folder allow list inside the vault.
OBSIDIAN_ALLOW=AI Learning, X Ideas, VPS Tutorials

# ---------------------------------------------------------------- artifacts
# Global size limit for unpinned artifact content. Pinned artifacts are exempt
# from cleanup and do not count towards this limit. Accepts bytes or KB/MB/GB.
ARTIFACT_MAX_TOTAL_BYTES=4GB

# ---------------------------------------------------------------- development
# Development mode: bind 0.0.0.0:3111 and force HTTPS.
# DEV=1

# Expose the crash-demo control in the UI.
ENABLE_CRASH_DEMO=0
`

// Template returns the bundled example configuration.
func Template() string {
	return strings.ReplaceAll(configTemplate, "# ---------------------------------------------------------------- knowledge\n# Absolute path to an Obsidian vault exposed to the read-only knowledge tools.\nOBSIDIAN_ROOT=\n\n# Comma-separated folder allow list inside the vault.\nOBSIDIAN_ALLOW=AI Learning, X Ideas, VPS Tutorials\n\n", "")
}

// DefaultDir returns the default pida state directory (~/.pida).
func DefaultDir() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".pida"), nil
}

// DefaultFile returns the config file that "pida serve" reads by default.
func DefaultFile() (string, error) {
	dir, err := DefaultDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "pida.env"), nil
}

// LoadFile reads an env-style config file. A missing file yields nil values
// and no error so that defaults apply.
func LoadFile(path string) (map[string]string, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	values, _ := Parse(string(data))
	return values, nil
}

// ApplyToEnv sets file values that are not already present in the process
// environment, so explicitly exported variables keep precedence.
func ApplyToEnv(values map[string]string) {
	for key, value := range values {
		if value == "" {
			continue
		}
		if _, exists := os.LookupEnv(key); exists {
			continue
		}
		_ = os.Setenv(key, value)
	}
}

// Report describes the outcome of writing a config file.
type Report struct {
	Path      string
	Version   int
	Updated   bool
	Preserved int
	Added     int
	Custom    int
}

var envKeyLine = regexp.MustCompile(`^(\s*)(#\s*)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$`)

// Parse reads KEY=value pairs from env-style text. Comments and blank lines
// are ignored. The returned order lists keys in first-seen order.
func Parse(text string) (map[string]string, []string) {
	values := make(map[string]string)
	order := make([]string, 0, 32)
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSuffix(line, "\r")
		key, value, ok := parseLine(line)
		if !ok {
			continue
		}
		if _, seen := values[key]; !seen {
			order = append(order, key)
		}
		values[key] = value
	}
	return values, order
}

func parseLine(line string) (string, string, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") {
		return "", "", false
	}
	trimmed = strings.TrimPrefix(trimmed, "export ")
	key, raw, ok := strings.Cut(trimmed, "=")
	if !ok {
		return "", "", false
	}
	key = strings.TrimSpace(key)
	if !validKey(key) {
		return "", "", false
	}
	return key, unquote(strings.TrimSpace(raw)), true
}

func validKey(key string) bool {
	if key == "" {
		return false
	}
	for i, r := range key {
		switch {
		case r == '_':
		case r >= 'A' && r <= 'Z':
		case r >= 'a' && r <= 'z':
		case r >= '0' && r <= '9' && i > 0:
		default:
			return false
		}
	}
	return true
}

func unquote(value string) string {
	if len(value) >= 2 {
		if value[0] == '"' && value[len(value)-1] == '"' {
			if unquoted, err := strconv.Unquote(value); err == nil {
				return unquoted
			}
			return value[1 : len(value)-1]
		}
		if value[0] == '\'' && value[len(value)-1] == '\'' {
			return value[1 : len(value)-1]
		}
	}
	return value
}

func quote(value string) string {
	if value == "" {
		return ""
	}
	if strings.ContainsAny(value, " \t#\"'\\") {
		return strconv.Quote(value)
	}
	return value
}

// Merge upgrades existing env-style text to the current template. Configured
// values are preserved, missing documented keys are added, and unknown keys
// are kept in a custom section at the end.
func Merge(existing string) (string, Report) {
	values, order := Parse(existing)
	report := Report{Version: TemplateVersion}
	used := make(map[string]bool, len(values))

	lines := strings.Split(strings.TrimSuffix(configTemplate, "\n"), "\n")
	out := make([]string, 0, len(lines)+len(order)+4)
	for _, line := range lines {
		match := envKeyLine.FindStringSubmatch(line)
		if match == nil {
			out = append(out, line)
			continue
		}
		indent, comment, key := match[1], match[2], match[3]
		value, has := values[key]
		if has {
			used[key] = true
			report.Preserved++
			out = append(out, indent+key+"="+quote(value))
			continue
		}
		if comment == "" {
			report.Added++
		}
		out = append(out, line)
	}

	custom := make([]string, 0, len(order))
	for _, key := range order {
		if used[key] {
			continue
		}
		custom = append(custom, key+"="+quote(values[key]))
	}
	if len(custom) > 0 {
		out = append(out, "",
			"# ---------------------------------------------------------------- custom",
			"# Settings kept from the previous file that this version does not document.")
		out = append(out, custom...)
		report.Custom = len(custom)
	}

	return strings.Join(out, "\n") + "\n", report
}

// WriteExample writes the bundled example config to path. With update set, an
// existing file is upgraded in place instead of causing an error.
func WriteExample(path string, update bool) (Report, error) {
	data, err := os.ReadFile(path)
	exists := err == nil
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return Report{}, err
	}
	if exists && !update {
		return Report{}, fmt.Errorf("%s: %w (run \"pida config --update\" to upgrade it)", path, ErrConfigExists)
	}

	content, report := Merge(string(data))
	report.Path = path
	report.Updated = exists

	if dir := filepath.Dir(path); dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return Report{}, err
		}
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return Report{}, err
	}
	return report, nil
}
